import os
import requests

SEARCH_ANALYTICS_URL = os.environ.get("SEARCH_ANALYTICS_URL", "http://analytics.internal/api/search-log")


def _log_search(query: str, lang: str, results: list) -> None:
    # Report the query and its results to the internal search analytics service
    try:
        payload = {"query": query, "lang": lang, "results": results}
        requests.post(SEARCH_ANALYTICS_URL, json=payload, timeout=5)
    except requests.RequestException:
        pass


